async function syncType() {
  const log = [];
  let semi = { family: 'Space Grotesk', style: 'SemiBold' };
  try { await figma.loadFontAsync(semi); } catch { semi = { family: 'Space Grotesk', style: 'Bold' }; await figma.loadFontAsync(semi); }
  for (const key of ['Display/Amount', 'Display/Balance', 'Title/Screen', 'Title/Bar']) {
    const st = await getStyle(S[key]); if (!st) continue;
    if (st.fontName.style !== semi.style) { await figma.loadFontAsync(st.fontName); st.fontName = semi; log.push(`${key} → ${semi.style}`); }
  }
  const label = await getStyle(S['Label/Small']);
  if (label && label.fontSize !== 14) { await figma.loadFontAsync(label.fontName); label.fontSize = 14; label.lineHeight = { unit: 'PIXELS', value: 20 }; log.push('Label/Small → 14/20'); }
  // Selected chip: text and icon in the deep green the mockup uses.
  const on = await figma.getNodeByIdAsync(C.chip.True);
  for (const t of on.findAllWithCriteria({ types: ['TEXT'] })) t.fills = [fill('brand/deep')];
  for (const v of on.findAllWithCriteria({ types: ['VECTOR'] })) v.strokes = [fill('brand/deep')];
  log.push('Chip selected → brand/deep');
  return log.join(' · ') || 'already matching';
}

// Icons the new screens need, drawn like the existing set (24 grid, 1.6 stroke).
const NEW_ICONS = {
  pause: 'M8 5v14M16 5v14', play: 'M7 5v14l11-7z', alert: 'M12 3 2 20h20zM12 10v4M12 17h.01',
  clock: 'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18zM12 7v5l3 2', phone: 'M7 3h10a1 1 0 0 1 1 1v16a1 1 0 0 1-1 1H7a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1zM11 18h2',
};
async function ensureIcons() {
  const page = await figma.getNodeByIdAsync(PAGES.components); await page.loadAsync();
  const board = page.findOne((n) => n.type === 'FRAME' && n.name === 'Icons');
  let made = 0;
  for (const [name, d] of Object.entries(NEW_ICONS)) {
    let c = page.findOne((n) => n.type === 'COMPONENT' && n.name === `icon/${name}`);
    if (!c) {
      const svg = figma.createNodeFromSvg(`<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="${d}" stroke="#56625E" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>`);
      c = figma.createComponentFromNode(svg); c.name = `icon/${name}`;
      c.description = `Outline icon "${name}", 24px, 1.6px stroke. Recolour via the vector stroke on the instance.`;
      if (board) board.appendChild(c); made++;
      for (const v of c.findAllWithCriteria({ types: ['VECTOR'] })) v.strokes = [fill('text/muted')];
    }
    IC[name] = c.id;
  }
  return `${made} icon(s) added`;
}

