// 5. Read me notes
// ---------------------------------------------------------------------------------------------
async function readmeNotes() {
  const page = await figma.getNodeByIdAsync(PAGES.readme); await page.loadAsync();
  const root = page.children.find((n) => n.name === 'Read me'); if (!root) return 'Read me frame not found (run round 3 first)';
  root.children.filter((n) => n.name.startsWith('Round 4')).forEach((n) => n.remove());
  const panel = (name) => { const p = col(14, name); p.resize(1464, 100); p.primaryAxisSizingMode = 'AUTO'; p.counterAxisSizingMode = 'FIXED'; p.cornerRadius = 24; p.fills = [fill('surface/card')]; outline(p); pad(p, 32); return p; };
  const a = panel('Round 4 · popups, recurring, notifications'); add(root, a);
  add(a, await text('Round 4 · popups, recurring, notifications (24 Oct 2026)', 'Heading/Section'));
  for (const l of [
    'Every popup is one bottom sheet (Components → Sheets & popups): full width and flush to the bottom, titled, 44px close, focus moves in and returns, Esc/backdrop close. One sheet at a time: a confirm replaces the sheet content instead of stacking a second dialog.',
    'Transaction detail: description, date, amount, category, paid with, paid by, account; Edit opens the full Add-transaction form in edit mode (same route, ?edit=id) instead of an amount-only box; Delete asks inside the same sheet, then a snackbar offers Undo (deletes are already soft).',
    'Destructive confirm: solid red button with white text (5.9:1), the safe choice focused first, the consequence in numbers (“Ghar’s balance goes back up by ₹29,400”).',
    'Filters move into a sheet: one selected style (brand), live “Show N”, Clear all. Period has its own small sheet.',
    'Recurring: month commitment on top; needs attention (stalled schedules with no next date), coming up, paused. Detail leads with the next payment and Mark paid / Skip; Pause/Resume and Delete at the end with confirms. Add and Edit are one form; edit can change every field.',
    'Notifications: grouped by day, Unread filter with count, plain icons, inline actions, whole row opens the item, link to settings. Settings labels now say what each switch controls; they only affect phone alerts.',
    'Overlays: popups are placed on their screens as hidden layers named “Overlay · … (show to review)”. The screen count stays 32.',
  ]) add(a, await text('• ' + l, 'Body/Regular'));
  const b = panel('Round 4 · colour and type check'); add(root, b);
  add(b, await text('Colour and type check against the mockup CSS', 'Heading/Section'));
  for (const l of colourLog.length ? colourLog : ['All variables already matched the mockup.']) add(b, await text('• ' + l, 'Body/Small', l.startsWith('off-palette') ? 'status/warning' : 'text/primary'));
  return `Read me → ${a.id}, ${b.id}`;
}

// ---------------------------------------------------------------------------------------------
(async () => {
  const results = [];
  try {
    vars = Object.fromEntries(await Promise.all(Object.entries(V).map(async ([k, id]) => [k, await figma.variables.getVariableByIdAsync(id)])));
    await Promise.all([['DM Sans', 'Medium'], ['DM Sans', 'SemiBold'], ['DM Sans', 'Regular'], ['Space Grotesk', 'Medium'], ['Space Grotesk', 'Bold']].map(([family, style]) => figma.loadFontAsync({ family, style })));
  } catch (e) { figma.closePlugin(`Setup failed: ${e.message}`); return; }

  let sheets = null;
  const steps = [
    ['Colours', syncColours],
    ['Type', syncType],
    ['Icons', ensureIcons],
    ['Sheets', async () => { sheets = await buildSheets(); return `${Object.keys(sheets).length} components`; }],
    ['Recurring', () => replaceScreen(SECTIONS.recurring, 'Recurring', buildRecurring)],
    ['View recurring', async () => { const r = await replaceScreen(SECTIONS.recurring, 'View recurring', buildViewRecurring); await overlayExisting(SECTIONS.recurring, 'View recurring', [[sheets.record, 'Record payment'], [sheets.pause, 'Pause schedule'], [sheets.deleteSchedule, 'Delete schedule']]); return r; }],
    ['Add recurring', () => replaceScreen(SECTIONS.recurring, 'Add recurring', (s, x) => recurringForm(s, x, false))],
    ['Edit recurring', () => replaceScreen(SECTIONS.recurring, 'Edit recurring', (s, x) => recurringForm(s, x, true))],
    ['Notifications', () => replaceScreen(SECTIONS.core, 'Notifications', buildNotifications)],
    ['Notification settings', () => replaceScreen(SECTIONS.settings, 'Notification settings', buildNotificationSettings)],
    ['Transaction overlays', () => overlayExisting(SECTIONS.core, 'Transactions', [[sheets.detail, 'Transaction detail'], [sheets.confirm, 'Delete transaction'], [sheets.filters, 'Filters'], [sheets.period, 'Period']])],
    ['Loose paints', bindLoosePaints],
    ['Read me', readmeNotes],
  ];
  const screensPage = await figma.getNodeByIdAsync(PAGES.screens);
  for (const [name, run] of steps) {
    try {
      if (!['Read me', 'Sheets', 'Icons', 'Loose paints'].includes(name)) await figma.setCurrentPageAsync(screensPage);
      results.push(`✓ ${name}: ${await run()}`);
    } catch (e) { results.push(`✗ ${name}: ${e.message}`); }
  }
  await figma.setCurrentPageAsync(screensPage);
  console.log(results.join('\n'));
  const failed = results.filter((r) => r.startsWith('✗')).length;
  figma.closePlugin(failed ? `Round 4: ${failed} step(s) failed — see the console (Plugins → Development → Show/Hide console)` : 'Round 4 applied: colours, type, sheets, recurring, notifications');
})();
